// The weapon registry: every gun the class screen can offer, the knife, and
// the two grenades, in one table. index.html builds its weapon slots, the
// class-screen cards, the HUD names and the bots' loadouts from here, so
// adding a weapon is one entry (generated by
// `python .tools/generate_weapon_definitions.py <id>`) plus its assets
// (`python .tools/import_weapon_assets.py`).
//
// Stats are the T6 weapon files' own: magazine, cadence, fire type, damage
// and the authored clip names. Range falloff, spread and kick live in
// weapon-ballistics.js, generated from the same files. No DOM or Three.js
// here so the table loads in node tests.

const degToRad = (degrees) => degrees * (Math.PI / 180);

// Create-a-class tabs, in the game's order. Each holds one equipped weapon.
export const WEAPON_CLASSES = Object.freeze({
  primary: Object.freeze({ id: 'primary', label: 'Primary', hint: 'Assault and sniper rifles', key: 'Digit1' }),
  secondary: Object.freeze({ id: 'secondary', label: 'Secondary', hint: 'Pistols', key: 'Digit2' }),
  lethal: Object.freeze({ id: 'lethal', label: 'Lethal', hint: 'Thrown with G', key: 'KeyG' }),
  tactical: Object.freeze({ id: 'tactical', label: 'Tactical', hint: 'Thrown with Q', key: 'KeyQ' }),
});
