// A fresh class: what a player spawns with before touching create-a-class.
export const DEFAULT_LOADOUT = Object.freeze({
  primary: 'm27',
  secondary: 'fiveseven',
  lethal: 'frag',
  tactical: 'smoke',
});

/** A random loadout for a bot: any rifle, any pistol, always the two grenades. */
export function randomLoadout(random = Math.random, table = WEAPONS) {
  const pick = (list) => list[Math.floor(random() * list.length)]?.id ?? null;
  return {
    primary: pick(weaponsOfClass('primary', table)) ?? DEFAULT_LOADOUT.primary,
    secondary: pick(weaponsOfClass('secondary', table)) ?? DEFAULT_LOADOUT.secondary,
    lethal: DEFAULT_LOADOUT.lethal,
    tactical: DEFAULT_LOADOUT.tactical,
  };
}

/**
 * Loadout order for the weapon wheel and the number keys: the primary in slot
 * 1, the secondary in slot 2. Returns the id one step from `current`.
 */
export function nextHeldWeapon(loadout, current, step = 1) {
  const held = ['primary', 'secondary'].map((cls) => loadout?.[cls]).filter(Boolean);
  if (!held.length) return null;
  const index = Math.max(0, held.indexOf(current));
  return held[((index + step) % held.length + held.length) % held.length];
}
